import{a as e,c as t,i as n,t as r}from"./app-C4mzCnKe.js";var i=JSON.parse(`{"path":"/agent-roster.html","title":"Agent 清单（13 个运行时 Agent）","lang":"zh-CN","frontmatter":{},"git":{},"filePathRelative":"agent-roster.md"}`),a={name:`agent-roster.md`};function o(r,i,a,o,s,c){return t(),n(`div`,null,[...i[0]||=[e(`<h1 id="agent-清单-13-个运行时-agent" tabindex="-1"><a class="header-anchor" href="#agent-清单-13-个运行时-agent"><span>Agent 清单（13 个运行时 Agent）</span></a></h1><p>两段式编排：<strong>主控</strong>做意图理解与规划，<strong>调度器</strong>做运行时派发。其余按「上下文不同 / 模型强度不同 / 节奏不同 / 状态所有权不同」切分。</p><table><thead><tr><th>#</th><th>Agent</th><th>面</th><th>核心职责</th><th>模型</th><th>节奏</th><th>写域（所有权）</th></tr></thead><tbody><tr><td>1</td><td><strong>主控</strong> Commander</td><td>门面</td><td>意图理解、目标/任务规划、子任务分解、结果整合、追问澄清</td><td>DeepSeek Pro</td><td>会话入口/按需</td><td>目标与任务清单</td></tr><tr><td>2</td><td><strong>调度器</strong> Runtime Orchestrator</td><td>决策</td><td>任务路由、并发/预算、协议执行、幂等、组装决策包、触发对账</td><td>DeepSeek Flash</td><td>事件驱动</td><td>任务队列、决策包</td></tr><tr><td>3</td><td><strong>策略师</strong> Strategist</td><td>决策</td><td>策略生成：因子假设→信号/进出场/仓位/风控门，产出机器可读 proposal</td><td>起草 Flash · 定稿 Pro</td><td>盘后为主</td><td>策略 proposal（草稿态）</td></tr><tr><td>4</td><td><strong>因子工坊</strong> Factor Lab</td><td>决策</td><td>因子定义/注册/版本、口径与来源绑定、因子 QC</td><td>Flash</td><td>盘后</td><td>因子字典（Schema 注册表）</td></tr><tr><td>5</td><td><strong>大盘分析师</strong> Macro Analyst</td><td>决策</td><td>大盘大势、板块/题材轮动、消息面机会</td><td>DeepSeek Pro</td><td>盘后日频</td><td>大势研判、板块机会清单</td></tr><tr><td>6</td><td><strong>盘中哨兵</strong> Intraday Sentinel</td><td>决策</td><td>盘中监听：涨跌停/异动/信号触发/风控阈值，触发即发事件</td><td>Flash</td><td>盘中实时</td><td>事件流（只发不落库）</td></tr><tr><td>7</td><td><strong>回测判决官</strong> Backtest Judge</td><td>裁决</td><td>回测：独立日超额、配对 vs 随机对照、分层切片；harness 是确定性代码</td><td>代码 + Flash 解读</td><td>按需</td><td>判决库（只读生产）</td></tr><tr><td>8</td><td><strong>对账官</strong> Reconciler</td><td>裁决</td><td>决策对账（事实：决策 vs 实际 T+N 结果）+ <strong>结果归因</strong>（因子/策略沿溯源图·信用传播），产出对账单 + 归因结论 + 回滚信号</td><td>DeepSeek Pro</td><td>T+N 收盘后</td><td>对账单、归因结论、回滚建议</td></tr><tr><td>9</td><td><strong>会话评估官</strong> Process Evaluator</td><td>裁决</td><td>评估会话过程（<strong>评估器</strong>：证据/边界/判定 + LLM Judge），trace 分析推理质量/工具效率/协议合规/成本</td><td>Pro + GLM 异源</td><td>异步批处理</td><td>过程评测报告、过程评估结论（只读 trace）</td></tr><tr><td>10</td><td><strong>数据管家</strong> Data Custodian</td><td>平台</td><td>数据维护：本地 duckdb + 线上获取，口径/单位/复权一致性，QC 门禁</td><td>Flash + 代码</td><td>盘后/按需</td><td>数据库、口径注册表</td></tr><tr><td>11</td><td><strong>知识馆长</strong> Knowledge Curator</td><td>平台</td><td>知识库维护：卡片去重/溯源/证据分级，争议异源裁定</td><td>Flash + Pro + GLM</td><td>异步</td><td>知识库、证据索引</td></tr><tr><td>12</td><td><strong>能力管家</strong> Capability Steward</td><td>平台</td><td>工具 + Skill 维护：注册/版本/契约测试，测试通过才晋级</td><td>Flash</td><td>按需</td><td>工具/Skill 注册表</td></tr><tr><td>13</td><td><strong>资产登记官</strong> Asset Registrar</td><td>平台</td><td>会话过程资产维护：蒸馏成决策/理由/结果/教训的结构化资产</td><td>Pro 蒸馏 + Flash</td><td>会话结束/异步</td><td>过程资产库（内容寻址）</td></tr></tbody></table><h2 id="两个关键设计" tabindex="-1"><a class="header-anchor" href="#两个关键设计"><span>两个关键设计</span></a></h2><ul><li><strong>主控只规划整合，不落库、不写判决库</strong> —— 写域由协议总线 ACL 强约束，防越权。</li><li><strong>协议设计（任务 8）是治理工件</strong> —— 由调度器执行、裁决面验证，不设运行时 Agent。</li></ul><h2 id="调度器的两个触发源" tabindex="-1"><a class="header-anchor" href="#调度器的两个触发源"><span>调度器的两个触发源</span></a></h2><p>调度器是运行时总调度，但它<strong>不是只被主控调用</strong>——它有两个触发源：</p><table><thead><tr><th>触发源</th><th>触发方式</th><th>典型任务</th><th>特点</th></tr></thead><tbody><tr><td><strong>主控</strong></td><td>会话入口 / 按需</td><td>用户意图 → 任务清单（含「派给哪个面」的规划）</td><td>有人参与，任务来自意图</td></tr><tr><td><strong>定时器</strong></td><td>cron 定时（盘后 / 盘前 / 定时复盘）</td><td>盘后对账、盘前预热、定时复盘、数据 QC</td><td>无人参与，任务来自时刻表</td></tr></tbody></table><blockquote><p>两者最终都落到调度器的<strong>同一条执行路径</strong>（任务队列 → 路由 → 并发/预算 → 幂等 → 组装决策包）。区别只在「任务从哪来」：一个来自主控的规划，一个来自定时器的时刻表。</p></blockquote><h2 id="每个-agent-在两条纵贯线上的位置" tabindex="-1"><a class="header-anchor" href="#每个-agent-在两条纵贯线上的位置"><span>每个 Agent 在两条纵贯线上的位置</span></a></h2><p>可观测（Span 类型）与自进化（进化角色）是横切关注点，<strong>每个 Agent 同时承担二者</strong>：</p><table><thead><tr><th>#</th><th>Agent</th><th>可观测产出（Span 类型）</th><th>进化角色（读/写哪个层）</th></tr></thead><tbody><tr><td>1</td><td>主控</td><td>回合 turn</td><td>读经验（效用检索）；不写可进化层</td></tr><tr><td>2</td><td>调度器</td><td>回合 turn</td><td>执行协议；不写可进化层</td></tr><tr><td>3</td><td>策略师</td><td>模型调用 llm + 检索 retrieve</td><td>写可进化 A（策略 proposal、调权重/改出场）</td></tr><tr><td>4</td><td>因子工坊</td><td>检索 retrieve + 模型调用 llm</td><td>写可进化 A（因子字典，4 类动作）</td></tr><tr><td>5</td><td>大盘分析师</td><td>模型调用 llm</td><td>写可进化 A（大势研判，作为 regime 输入）</td></tr><tr><td>6</td><td>盘中哨兵</td><td>事件 event（只发不落库）</td><td>触发对账；不写可进化层</td></tr><tr><td>7</td><td>回测判决官</td><td>判决 judge + 风控校验 guard（确定性代码）</td><td>冻结层（不可进化）；供归因统计</td></tr><tr><td>8</td><td>对账官</td><td>判决 judge + 模型调用 llm</td><td>结果归因（信用传播）→ 驱动策略进化</td></tr><tr><td>9</td><td>会话评估官</td><td>模型调用 llm + 检索 retrieve（打标）</td><td>过程评估（评估器）→ 驱动过程进化</td></tr><tr><td>10</td><td>数据管家</td><td>数据取数 data + 风控校验 guard</td><td>冻结层（口径契约）；供 QC 门禁</td></tr><tr><td>11</td><td>知识馆长</td><td>检索 retrieve + 模型调用 llm</td><td>写可进化 B（知识卡，带证据等级）</td></tr><tr><td>12</td><td>能力管家</td><td>工具调用 tool</td><td>写可进化 B（prompt/skill/协议）</td></tr><tr><td>13</td><td>资产登记官</td><td>检索 retrieve（效用重排）+ 打标</td><td>写可进化 B（决策资产三元组 + 溯源边）</td></tr></tbody></table><blockquote><p>规律：<strong>决策面/平台面产出 + 写可进化层；裁决面只读 + 归因；冻结层（判决器/口径/回测引擎）永不进化。</strong> 这条规律把「谁产生判断」与「谁验证判断」在两条纵贯线上也分开了。</p></blockquote>`,13)]])}var s=r(a,[[`render`,o]]);export{i as _pageData,s as default};